Page._content:
/* ==========================================
   1. 全局变量与卡片实心化（去除透明度）
   ========================================== */
:root {
  --trans-light: #ffffff; /* 纯白实心 */
  --trans-dark: #191919;  /* 纯黑实心 */
  --border-style: 1px solid rgb(169, 169, 169);
  --backdrop-filter: none; /* 彻底去除毛玻璃 */
}

/* 首页文章卡片 */
#recent-posts > .recent-post-item {
  background: var(--trans-light);
  backdrop-filter: var(--backdrop-filter);
  border-radius: 25px;
  border: var(--border-style);
}

/* 首页侧栏卡片 */
#aside-content .card-widget {
  background: var(--trans-light);
  backdrop-filter: var(--backdrop-filter);
  border-radius: 18px;
  border: var(--border-style);
}

/* 文章页、归档页、普通页面 */
div#post,
div#page,
div#archive {
  background: var(--trans-light);
  backdrop-filter: var(--backdrop-filter);
  border: var(--border-style);
  border-radius: 20px;
}

/* 夜间模式遮罩实心化 */
[data-theme="dark"] #recent-posts > .recent-post-item,
[data-theme="dark"] #aside-content .card-widget,
[data-theme="dark"] div#post,
[data-theme="dark"] div#archive,
[data-theme="dark"] div#page {
  background: var(--trans-dark);
}

/* 夜间模式页脚页头遮罩透明 (保留透明) */
[data-theme="dark"] #footer::before {
  background: transparent !important;
}
[data-theme="dark"] #page-header::before {
  background: transparent !important;
}

/* 阅读模式实心化 */
.read-mode #aside-content .card-widget {
  background: #9eccab !important;
}
.read-mode div#post {
  background: #9eccab !important;
}

/* 夜间模式下的阅读模式实心化 */
[data-theme="dark"] .read-mode #aside-content .card-widget {
  background: #191919 !important;
  color: #ffffff;
}
[data-theme="dark"] .read-mode div#post {
  background: #191919 !important;
  color: #ffffff;
}

/* 翻页按钮居中 */
#pagination {
  width: 100%;
  margin: auto;
}

/* ==========================================
   2. 导航栏与菜单设置
   ========================================== */
/* 一级菜单居中 */
#nav .menus_items {
  position: absolute !important;
  width: fit-content !important;
  left: 50% !important;
  transform: translateX(-50%) !important;
}
/* 子菜单横向展示 */
#nav .menus_items .menus_item:hover .menus_item_child {
  display: flex !important;
}
.menus_items .menus_item:nth-child(2) .menus_item_child {
  left: -125px;
}

/* ==========================================
   3. 侧边栏卡片特效
   ========================================== */
/* 侧边栏个人信息卡片动态渐变色 */
#aside-content > .card-widget.card-info {
  background: linear-gradient(
    -45deg,
    #e8d8b9,
    #eccec5,
    #a3e9eb,
    #bdbdf0,
    #eec1ea
  );
  box-shadow: 0 0 5px rgb(66, 68, 68);
  position: relative;
  background-size: 400% 400%;
  -webkit-animation: Gradient 10s ease infinite;
  -moz-animation: Gradient 10s ease infinite;
  animation: Gradient 10s ease infinite !important;
}
/* 侧边栏个人信息卡片自定义背景图 */
#aside-content > .card-widget.card-info {
  /* 把这里的路径换成你自己的图片路径 */
  background: url('/img/bj1.png') no-repeat center center !important;
  background-size: cover !important; /* 让图片铺满整个卡片 */
  box-shadow: 0 0 5px rgb(66, 68, 68);
  position: relative;
}


/* 如果你想加一层半透明遮罩，让背景图不至于太花导致文字看不清，可以把下面的代码也加上去 */
#aside-content > .card-widget.card-info::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: rgba(0, 0, 0, 0.4); /* 透明度 0.2，数字越小图越清晰，越大图越白 */
  border-radius: inherit;
  z-index: -1; /* 放在底层 */
}

/* 黑夜模式适配 */
[data-theme="dark"] #aside-content > .card-widget.card-info {
  background: #191919;
}

/* 个人信息Follow me按钮 */
#aside-content > .card-widget.card-info > #card-info-btn {
  background-color: #3eb8be;
  border-radius: 8px;
}

/* ==========================================
   4. 加载进度条 (Pace)
   ========================================== */
.pace {
    -webkit-pointer-events: none;
    pointer-events: none;
    -webkit-user-select: none;
    -moz-user-select: none;
    user-select: none;
    z-index: 2000;
    position: fixed;
    margin: auto;
    top: 4px;
    left: 0;
    right: 0;
    height: 8px;
    border-radius: 8px;
    width: 7rem;
    background: #eaecf2;
    border: 1px #e3e8f7;
    overflow: hidden
}
.pace-inactive .pace-progress {
    opacity: 0;
    transition: .3s ease-in
}
.pace .pace-progress {
    -webkit-box-sizing: border-box;
    -moz-box-sizing: border-box;
    -ms-box-sizing: border-box;
    -o-box-sizing: border-box;
    box-sizing: border-box;
    -webkit-transform: translate3d(0, 0, 0);
    -moz-transform: translate3d(0, 0, 0);
    -ms-transform: translate3d(0, 0, 0);
    -o-transform: translate3d(0, 0, 0);
    transform: translate3d(0, 0, 0);
    max-width: 200px;
    position: absolute;
    z-index: 2000;
    display: block;
    top: 0;
    right: 100%;
    height: 100%;
    width: 100%;
    background: linear-gradient(to right, #43cea2, #3866ca);
    animation: gradient 2s ease infinite;
    background-size: 200%
}
.pace.pace-inactive {
    opacity: 0;
    transition: .3s;
    top: -8px
}

/* ==========================================
   5. 文章标题风车效果
   ========================================== */
h1::before, h2::before, h3::before, h4::before, h5::before, h6::before {
  -webkit-animation: ccc 4s linear infinite;
  animation: ccc 4s linear infinite;
}
@-webkit-keyframes ccc {
  0% { -webkit-transform: rotate(0deg); transform: rotate(0deg); }
  to { -webkit-transform: rotate(-1turn); transform: rotate(-1turn); }
}
@keyframes ccc {
  0% { -webkit-transform: rotate(0deg); transform: rotate(0deg); }
  to { -webkit-transform: rotate(-1turn); transform: rotate(-1turn); }
}
#content-inner.layout h1::before { color: #ef50a8; margin-left: -1.55rem; font-size: 1.3rem; margin-top: -0.23rem; }
#content-inner.layout h2::before { color: #fb7061; margin-left: -1.35rem; font-size: 1.1rem; margin-top: -0.12rem; }
#content-inner.layout h3::before { color: #ffbf00; margin-left: -1.22rem; font-size: 0.95rem; margin-top: -0.09rem; }
#content-inner.layout h4::before { color: #a9e000; margin-left: -1.05rem; font-size: 0.8rem; margin-top: -0.09rem; }
#content-inner.layout h5::before { color: #57c850; margin-left: -0.9rem; font-size: 0.7rem; margin-top: 0rem; }
#content-inner.layout h6::before { color: #5ec1e0; margin-left: -0.9rem; font-size: 0.66rem; margin-top: 0rem; }
#content-inner.layout h1:hover, #content-inner.layout h2:hover, #content-inner.layout h3:hover, #content-inner.layout h4:hover, #content-inner.layout h5:hover, #content-inner.layout h6:hover { color: var(--theme-color); }
#content-inner.layout h1:hover::before, #content-inner.layout h2:hover::before, #content-inner.layout h3:hover::before, #content-inner.layout h4:hover::before, #content-inner.layout h5:hover::before, #content-inner.layout h6:hover::before {
  color: var(--theme-color);
  -webkit-animation: ccc 6s linear infinite;
  animation: ccc 6s linear infinite;
}

/* ==========================================
   6. 波浪特效 (青白色)
   ========================================== */
.main-hero-waves-area {
  width: 100%;
  position: absolute;
  left: 0;
  bottom: -11px;
  z-index: 5;
}
.waves-area .waves-svg {
  width: 100%;
  height: 5rem;
}
.parallax > use {
  animation: move-forever 25s cubic-bezier(0.55, 0.5, 0.45, 0.5) infinite;
}
.parallax > use:nth-child(1) { animation-delay: -2s; animation-duration: 7s; fill: rgba(224, 247, 250, 0.7); }
.parallax > use:nth-child(2) { animation-delay: -3s; animation-duration: 10s; fill: rgba(224, 247, 250, 0.5); }
.parallax > use:nth-child(3) { animation-delay: -4s; animation-duration: 13s; fill: rgba(224, 247, 250, 0.3); }
.parallax > use:nth-child(4) { animation-delay: -5s; animation-duration: 20s; fill: #E0F7FA; }

[data-theme="dark"] .parallax > use:nth-child(1) { fill: rgba(50, 90, 95, 0.6); }
[data-theme="dark"] .parallax > use:nth-child(2) { fill: rgba(40, 80, 85, 0.4); }
[data-theme="dark"] .parallax > use:nth-child(3) { fill: rgba(30, 70, 75, 0.2); }
[data-theme="dark"] .parallax > use:nth-child(4) { fill: #1a3a3e; }

@keyframes move-forever {
  0% { transform: translate3d(-90px, 0, 0); }
  100% { transform: translate3d(85px, 0, 0); }
}
@media (max-width: 768px) {
  .waves-area .waves-svg { height: 40px; min-height: 40px; }
}

/* ==========================================
   7. 页脚与音乐播放器
   ========================================== */
#footer {
  background: transparent !important;
}
.aplayer.aplayer-fixed.aplayer-narrow .aplayer-body {
  left: -66px !important;
}
.aplayer.aplayer-fixed.aplayer-narrow .aplayer-body:hover {
  left: 0 !important;
}

/* ==========================================
   8. 顶部栏与手机侧边栏 (实心化)
   ========================================== */
#page-header.nav-fixed #nav {
  background: #f6eff6 !important; 
}
[data-theme=dark] #page-header.nav-fixed #nav {
  background: #2a2a2a !important;
}
#nav .show {
  background: #f6eff6 !important;
}
[data-theme=dark] #nav .show {
  background: #2a2a2a !important;
}
#sidebar #sidebar-menus.open {
  background: #f6eff6 !important;
  border-radius: 6px 0 0 6px;
}
[data-theme=dark] #sidebar #sidebar-menus.open {
  background: #2a2a2a !important;
  border-radius: 6px 0 0 6px;
}


/* ==========================================
   10. 字体声明与夜间发光特效
   ========================================== */

/* =========================================
   终极本地字体组合：霞鹜文楷 + Maple Mono
   ========================================= */

/* 1. 引入本地霞鹜文楷 (中文) */
@font-face {
  font-family: 'LXGW WenKai';
  src: url('/font/LXGWWenKai-Regular.ttf') format('truetype');
  font-weight: normal;
  font-style: normal;
  font-display: swap;
}

/* 2. 引入本地 Maple Mono (英文/代码) */
@font-face {
  font-family: 'Maple Mono';
  src: url('/font/MapleMono.woff2') format('woff2');
  font-weight: normal;
  font-style: normal;
  font-display: swap;
}

/* 3. 全局应用 (英文优先 Maple Mono，中文匹配霞鹜文楷) */
body, p, span, a, div, h1, h2, h3, h4, h5, h6, #nav, #site-title, #site-subtitle, .post-content, #article-container, .card-widget, #footer-wrap {
  font-family: 'Maple Mono', 'LXGW WenKai', 'PingFang SC', 'Microsoft YaHei', sans-serif !important;
  font-weight: 500 !important; 
}

/* 4. 针对标题加粗，保持层级感 */
h1, h2, h3, h4, h5, h6 {
  font-weight: bold !important;
}

/* 5. 代码块保护 (让代码块也使用 Maple Mono) */
code, pre, kbd, samp, .highlight, .highlight pre, .highlight span, figure.highlight * {
  font-family: 'Maple Mono', 'Consolas', 'Monaco', monospace !important;
  font-weight: normal !important;
  letter-spacing: 0 !important;
}

/* =========================================
   🚨 终极保护：拯救被挤没的 KaTeX 公式
   ========================================= */
.katex, .katex * {
  font-family: 'KaTeX_Math', 'KaTeX_Main', 'Times New Roman', serif !important;
  font-weight: normal !important; 
  letter-spacing: 0 !important; /* 绝对不能加字间距，否则公式会隐形 */
}


/* 日间模式不生效 */
[data-theme="light"] #site-name,
[data-theme="light"] #site-title,
[data-theme="light"] #site-subtitle,
[data-theme="light"] #post-info {
  animation: none;
}
/* 夜间模式生效 */
[data-theme="dark"] #site-name,
[data-theme="dark"] #site-title {
  animation: light_15px 10s linear infinite;
}
[data-theme="dark"] #site-subtitle {
  animation: light_10px 10s linear infinite;
}
[data-theme="dark"] #post-info {
  animation: light_5px 10s linear infinite;
}

/* 关键帧描述 */
@keyframes light_15px {
  0% { text-shadow: #5636ed 0 0 15px; }
  12.5% { text-shadow: #11ee5e 0 0 15px; }
  25% { text-shadow: #f14747 0 0 15px; }
  37.5% { text-shadow: #f1a247 0 0 15px; }
  50% { text-shadow: #b347f1 0 0 15px; }
  62.5% { text-shadow: #002afa 0 0 15px; }
  75% { text-shadow: #ed709b 0 0 15px; }
  87.5% { text-shadow: #39c5bb 0 0 15px; }
  100% { text-shadow: #5636ed 0 0 15px; }
}
@keyframes light_10px {
  0% { text-shadow: #5636ed 0 0 10px; }
  12.5% { text-shadow: #11ee5e 0 0 10px; }
  25% { text-shadow: #f14747 0 0 10px; }
  37.5% { text-shadow: #f1a247 0 0 10px; }
  50% { text-shadow: #b347f1 0 0 10px; }
  62.5% { text-shadow: #002afa 0 0 10px; }
  75% { text-shadow: #ed709b 0 0 10px; }
  87.5% { text-shadow: #39c5bb 0 0 10px; }
  100% { text-shadow: #5636ed 0 0 10px; }
}
@keyframes light_5px {
  0% { text-shadow: #5636ed 0 0 5px; }
  12.5% { text-shadow: #11ee5e 0 0 5px; }
  25% { text-shadow: #f14747 0 0 5px; }
  37.5% { text-shadow: #f1a247 0 0 15px; }
  50% { text-shadow: #b347f1 0 0 5px; }
  62.5% { text-shadow: #002afa 0 0 5px; }
  75% { text-shadow: #ed709b 0 0 5px; }
  87.5% { text-shadow: #39c5bb 0 0 5px; }
  100% { text-shadow: #5636ed 0 0 5px; }
}

/* ==========================================
   11. 评论输入框提示与 Owo 动画
   ========================================== */
#owo-big {
    position: fixed;
    align-items: center;
    background-color: rgb(255, 255, 255);
    border: 1px #aaa solid;
    border-radius: 10px;
    z-index: 9999;
    display: none;
    transform: translate(0, -105%);
    overflow: hidden;
    animation: owoIn 0.3s cubic-bezier(0.42, 0, 0.3, 1.11);
}
[data-theme=dark] #owo-big {
    background-color: #4a4a4a
}
#owo-big img {
    width: 100%;
}
@keyframes owoIn {
    0% { transform: translate(0, -95%); opacity: 0; }
    100% { transform: translate(0, -105%); opacity: 1; }
}

.el-input.el-input--small.el-input-group.el-input-group--prepend:nth-child(1):before { content: '输入QQ号会自动获取昵称和头像🐧'; }
.el-input.el-input--small.el-input-group.el-input-group--prepend:nth-child(2):before { content: '收到回复将会发送到您的邮箱📧'; }
.el-input.el-input--small.el-input-group.el-input-group--prepend:nth-child(3):before { content: '可以通过昵称访问您的网站🔗'; }
.el-input.el-input--small.el-input-group.el-input-group--prepend:focus-within::before,
.el-input.el-input--small.el-input-group.el-input-group--prepend:focus-within::after { display: block; }

.el-input.el-input--small.el-input-group.el-input-group--prepend::before {
    display: none;
    position: absolute;
    top: -60px;
    white-space: nowrap;
    border-radius: 10px;
    left: 50%;
    transform: translate(-50%);
    padding: 14px 18px;
    background: #444;
    color: #fff;
}
.el-input.el-input--small.el-input-group.el-input-group--prepend::after {
    display: none;
    content: '';
    position: absolute;
    border: 12px solid transparent;
    border-top-color: #444;
    left: 50%;
    transform: translate(-50%, -48px);
}

