#footer-wrap a {
  border-radius: 30px;
}

/* 1. 给整个页脚加一层浅浅的黑色层，不改变原有排版 */
#footer-wrap {
  padding: 20px 20px;
  background: rgba(0, 0, 0, 0.25) !important; /* 浅浅的黑色遮罩 */
  border-radius: 15px 15px 0 0; /* 稍微带点圆角看着舒服点，不喜欢可以删掉 */
}

/* 2. 只针对底部的版权、框架、旅行者号进行居中 */
#footer-wrap .copyright,
#footer-wrap .framework-info,
#footer-wrap .footer_custom_text,
#footer-wrap #workboard,
#footer-wrap #ghbdages {
  text-align: center !important; /* 文字居中 */
  display: block !important;
  margin: 8px auto !important;
  color: rgba(255, 255, 255, 0.85) !important; /* 稍微提亮一点文字，跟浅黑底更搭配 */
}

/* 确保旅行者号那一块和徽章居中 */
#footer-wrap #workboard,
#footer-wrap #ghbdages {
  display: flex !important;
  justify-content: center !important;
  flex-wrap: wrap !important;
}

/* 页脚心跳动画 */
#heartbeat {
  color: red;
  animation: iconAnimate 1s ease-in-out infinite;
}
@-moz-keyframes iconAnimate {
  0%, 100% { transform: scale(1); }
  10%, 30% { transform: scale(0.9); }
  20%, 40%, 60%, 80% { transform: scale(1.1); }
  50%, 70% { transform: scale(1.1); }
}
@-webkit-keyframes iconAnimate {
  0%, 100% { transform: scale(1); }
  10%, 30% { transform: scale(0.9); }
  20%, 40%, 60%, 80% { transform: scale(1.1); }
  50%, 70% { transform: scale(1.1); }
}
@-o-keyframes iconAnimate {
  0%, 100% { transform: scale(1); }
  10%, 30% { transform: scale(0.9); }
  20%, 40%, 60%, 80% { transform: scale(1.1); }
  50%, 70% { transform: scale(1.1); }
}
@keyframes iconAnimate {
  0%, 100% { transform: scale(1); }
  10%, 30% { transform: scale(0.9); }
  20%, 40%, 60%, 80% { transform: scale(1.1); }
  50%, 70% { transform: scale(1.1); }
}

/* =========================================
   夜间模式：压暗侧边栏个人信息卡片（头像区）
========================================= */

/* 针对夜间模式下的卡片信息区 */
[data-theme="dark"] #aside-content > .card-widget.card-info {
  position: relative;
}

/* 利用伪元素在图片上盖一层黑色半透明遮罩，这样背景图还是能看出来，但是不刺眼了 */
[data-theme="dark"] #aside-content > .card-widget.card-info::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-color: rgba(0, 0, 0, 0.5); /* 这里的 0.5 是暗度，数值越大越黑 */
  border-radius: inherit; /* 继承原本的圆角，防止遮罩溢出 */
  z-index: 0; /* 放在底层 */
}

/* 确保卡片里的文字、头像、按钮在遮罩上方，且不被遮挡 */
[data-theme="dark"] #aside-content > .card-widget.card-info > * {
  position: relative;
  z-index: 1; 
}

/* 顺便把头像稍微调暗一点点，显得不突兀 */
[data-theme="dark"] #aside-content .card-info .avatar-img {
  filter: brightness(0.85) !important;
}

/* 如果觉得卡片自带的白色阴影太亮，也可以一并去掉 */
[data-theme="dark"] #aside-content > .card-widget.card-info {
  box-shadow: 0 0 10px rgba(0, 0, 0, 0.5) !important; 
}

/* =========================================
   回到顶部按钮：完美居中 + 显示 % 号版
   ========================================= */

/* 1. 容器强制居中 */
#rightside #go-up {
  display: flex !important;
  justify-content: center !important;
  align-items: center !important;
  overflow: hidden !important; /* 防止内容溢出撑破 */
}

/* 2. 隐藏多余的空标签 */
#rightside #go-up .scroll-percent {
  display: none !important;
}

/* 3. 默认状态下：显示箭头，隐藏数字 */
#rightside #go-up i.fas.fa-arrow-up {
  display: block !important;
  font-size: 1.1rem !important;
  line-height: 1 !important;
  margin: 0 !important;
}

#rightside #go-up #percent {
  display: none !important;
}

/* 4. 鼠标悬停状态：隐藏箭头，显示数字和 % */
#rightside #go-up:hover i.fas.fa-arrow-up {
  display: none !important;
}

#rightside #go-up:hover #percent {
  display: flex !important; /* 使用 flex 保证数字和 % 在同一水平线 */
  justify-content: center !important;
  align-items: baseline !important; /* baseline 让 % 号的底部与数字对齐 */
  font-size: 13px !important; /* 整体字号稍微调小一点点，防止 100% 时撑破 */
  font-weight: bold !important;
  line-height: 1 !important;
  margin: 0 !important;
}

/* 5. 显式显示 % 号，并稍微调整大小让它看起来更精致 */
#rightside #go-up #percent span {
  display: block !important; /* 强制显示 % 号 */
  font-size: 10px !important; /* % 号字号比数字小一点更好看 */
  margin-left: 1px !important;
}


/* 头像呼吸灯 */
[data-theme="light"] .avatar-img {
