   ========================================== */
#fps {
  position: fixed;
  /* 向右上方移动：你可以根据喜好微调这里的像素值 */
  left: 25px; 
  bottom: 25px; 
  z-index: 1919810;

  /* 基础质感 */
  padding: 5px 10px !important;
  border-radius: 8px !important;
  font-family: 'Consolas', 'Monaco', monospace !important; /* 使用等宽字体，更像黑客数据 */
  font-weight: bold !important;
  font-size: 13px !important;
