}

/* 夜间模式 */
[data-theme="dark"] #fps {
  background-color: rgba(25, 25, 25, 0.85);
  backdrop-filter: blur(8px); /* 毛玻璃质感 */
  -webkit-backdrop-filter: blur(8px);
  color: #3eb8be !important; /* 文字变成青色 */
  border-color: rgba(62, 184, 190, 0.5); /* 青色半透明边框 */
