/* ==========================================
   10. 字体声明与夜间发光特效
   ========================================== */

/* =========================================
   终极本地字体组合：霞鹜文楷 + Maple Mono
   ========================================= */

/* 1. 引入本地霞鹜文楷 (中文) */
@font-face {
  font-family: 'LXGW WenKai';
  src: url('/font/LXGWWenKai-Regular.ttf') format('truetype');
  font-weight: normal;
  font-style: normal;
  font-display: swap;
}

/* 2. 引入本地 Maple Mono (英文/代码) */
@font-face {
  font-family: 'Maple Mono';
  src: url('/font/MapleMono.woff2') format('woff2');
  font-weight: normal;
  font-style: normal;
  font-display: swap;
}

/* 3. 全局应用 (英文优先 Maple Mono，中文匹配霞鹜文楷) */
body, p, span, a, div, h1, h2, h3, h4, h5, h6, #nav, #site-title, #site-subtitle, .post-content, #article-container, .card-widget, #footer-wrap {
  font-family: 'Maple Mono', 'LXGW WenKai', 'PingFang SC', 'Microsoft YaHei', sans-serif !important;
  font-weight: 500 !important; 
}

/* 4. 针对标题加粗，保持层级感 */
h1, h2, h3, h4, h5, h6 {
  font-weight: bold !important;
}

/* 5. 代码块保护 (让代码块也使用 Maple Mono) */
code, pre, kbd, samp, .highlight, .highlight pre, .highlight span, figure.highlight * {
  font-family: 'Maple Mono', 'Consolas', 'Monaco', monospace !important;
  font-weight: normal !important;
  letter-spacing: 0 !important;
}

/* =========================================
   🚨 终极保护：拯救被挤没的 KaTeX 公式
   ========================================= */
.katex, .katex * {
  font-family: 'KaTeX_Math', 'KaTeX_Main', 'Times New Roman', serif !important;
  font-weight: normal !important; 
  letter-spacing: 0 !important; /* 绝对不能加字间距，否则公式会隐形 */
}


/* 日间模式不生效 */
[data-theme="light"] #site-name,
[data-theme="light"] #site-title,
[data-theme="light"] #site-subtitle,
[data-theme="light"] #post-info {
  animation: none;
