  line-height: 1 !important;
  margin: 0 !important;
}

#rightside #go-up #percent {
  display: none !important;
}

/* 4. 鼠标悬停状态：隐藏箭头，显示数字和 % */
#rightside #go-up:hover i.fas.fa-arrow-up {
  display: none !important;
}

#rightside #go-up:hover #percent {
  display: flex !important; /* 使用 flex 保证数字和 % 在同一水平线 */
  justify-content: center !important;
  align-items: baseline !important; /* baseline 让 % 号的底部与数字对齐 */
  font-size: 13px !important; /* 整体字号稍微调小一点点，防止 100% 时撑破 */
  font-weight: bold !important;
  line-height: 1 !important;
  margin: 0 !important;
}

/* 5. 显式显示 % 号，并稍微调整大小让它看起来更精致 */
#rightside #go-up #percent span {
  display: block !important; /* 强制显示 % 号 */
  font-size: 10px !important; /* % 号字号比数字小一点更好看 */
  margin-left: 1px !important;
}


