}

/* ==========================================
   自定义网页滚动条 (适配你的青色主题)
   ========================================== */

/* 1. 滚动条整体宽度 */
::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}

/* 2. 滚动条轨道 (背景) */
::-webkit-scrollbar-track {
  background-color: rgba(0, 0, 0, 0.05);
  border-radius: 2em;
}

/* 3. 滚动条滑块 (你平时拖动的那个条) */
::-webkit-scrollbar-thumb {
  background-color: #3eb8be; /* 这里用的是你侧边按钮的青色，你可以随便改 */
  background-image: -webkit-linear-gradient(
    45deg,
    rgba(255, 255, 255, 0.2) 25%,
    transparent 25%,
    transparent 50%,
    rgba(255, 255, 255, 0.2) 50%,
    rgba(255, 255, 255, 0.2) 75%,
    transparent 75%,
    transparent
  );
  border-radius: 2em;
}

/* 4. 鼠标悬停在滑块上时的颜色 (稍微变亮一点) */
::-webkit-scrollbar-thumb:hover {
  background-color: #55c5cb;
}

