/* =========================================
   终极本地字体组合：霞鹜文楷 + Maple Mono
   ========================================= */

/* 1. 引入本地霞鹜文楷 (中文) */
@font-face {
  font-family: 'LXGW WenKai';
  src: url('/font/LXGWWenKai-Regular.ttf') format('truetype');
  font-weight: normal;
  font-style: normal;
  font-display: swap;
}

/* 2. 引入本地 Maple Mono (英文/代码) */
@font-face {
  font-family: 'Maple Mono';
  src: url('/font/MapleMono.woff2') format('woff2');
  font-weight: normal;
  font-style: normal;
  font-display: swap;
}

/* 3. 全局应用 (英文优先 Maple Mono，中文匹配霞鹜文楷) */
body, p, span, a, div, h1, h2, h3, h4, h5, h6, #nav, #site-title, #site-subtitle, .post-content, #article-container, .card-widget, #footer-wrap {
  font-family: 'Maple Mono', 'LXGW WenKai', 'PingFang SC', 'Microsoft YaHei', sans-serif !important;
