}

/* 4. 针对标题加粗，保持层级感 */
h1, h2, h3, h4, h5, h6 {
  font-weight: bold !important;
}

/* 5. 代码块保护 (让代码块也使用 Maple Mono) */
code, pre, kbd, samp, .highlight, .highlight pre, .highlight span, figure.highlight * {
  font-family: 'Maple Mono', 'Consolas', 'Monaco', monospace !important;
  font-weight: normal !important;
  letter-spacing: 0 !important;
}

/* =========================================
   🚨 终极保护：拯救被挤没的 KaTeX 公式
   ========================================= */
.katex, .katex * {
  font-family: 'KaTeX_Math', 'KaTeX_Main', 'Times New Roman', serif !important;
  font-weight: normal !important; 
  letter-spacing: 0 !important; /* 绝对不能加字间距，否则公式会隐形 */
